 function pythonRunStale(r){return r.code!==pythonEditor()||(r.pseudocode!==undefined&&r.pseudocode!==ownCode());}
 function pythonRunsHTML(){const runs=(state.pythonRuns||[]).filter(r=>(r.checkId||1)===planCheck());return runs.length?`<details class="support-details"><summary>${bi(CHALLENGE.runs)} · ${runs.length}</summary><p>${bi(CHALLENGE.runEvidence)}</p>${runs.map((r,i)=>`<section class="saved-test"><strong>${i+1} · ${esc(r.at)}</strong><p>${bi(CHALLENGE.inputs)}: ${(r.inputs||[]).map(v=>esc(v.value===''?txt(CHALLENGE.emptyInput):v.value)).join(' → ')||'—'}</p><pre class="python-console">${esc(r.output||'')}</pre>${pythonRunStale(r)?`<p class="hint">${bi(CHALLENGE.changed)}</p>`:''}<details><summary>${bi(CHALLENGE.runSource)}</summary><pre>${esc(r.pseudocode||'—')}</pre><pre>${esc(r.code)}</pre></details></section>`).join('')}</details>`:'';}
 function pythonPage(){const latest=(state.pythonRuns||[]).filter(r=>(r.checkId||1)===planCheck()).at(-1);return `<div class="challenge-page"><h2>${bi(CHALLENGE.pythonTitle)}</h2><p>${bi(CHALLENGE.pythonIntro)}</p><p class="notice blue">${bi(CHALLENGE.pythonBrief)}</p>${challengeSource()}<details class="support-details"><summary>${bi(CHALLENGE.pythonHelp)}</summary><div class="table-scroll"><table class="challenge-table"><thead><tr>${CHALLENGE.translation[0].map(t=>`<th>${bi(t)}</th>`).join('')}</tr></thead><tbody>${CHALLENGE.translation.slice(1).map(row=>`<tr>${row.map((t,i)=>`<td>${i<2?`<code>${esc(txt(t))}</code>`:bi(t)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><h3>${bi(CHALLENGE.model)}</h3><p>${bi(B('Compare this link-question example with your own plan. Adapt the question and advice; copying the example alone does not demonstrate independent translation.','Bandingkan contoh soalan pautan ini dengan pelan sendiri. Sesuaikan soalan dan nasihat; menyalin contoh sahaja tidak menunjukkan terjemahan bebas.','将此链接问题示例与你的计划对照，并调整问题和建议。仅复制示例不能证明能独立转换。'))}</p><pre class="python-console">${esc(txt(CHALLENGE.pythonModel))}</pre></details><p>${bi(CHALLENGE.pythonPractice)}</p>${question(FIELD[planField('pythonPrediction')])}<label for="pythonCode">${bi(FIELD[planField('pythonCode')].prompt)}</label><textarea id="pythonCode" class="python-editor" data-field="${planField('pythonCode')}" spellcheck="false">${esc(pythonEditor())}</textarea><div class="button-row"><button type="button" class="primary" data-action="run-python">${optionLabel(CHALLENGE.run)}</button><button type="button" data-action="stop-python">${optionLabel(CHALLENGE.stop)}</button><button type="button" data-action="download-python">${optionLabel(CHALLENGE.download)}</button><button type="button" data-action="reset-python">${optionLabel(CHALLENGE.reset)}</button></div><h3>${bi(CHALLENGE.output)}</h3><pre id="pythonConsole" class="python-console" role="log">${esc(latest?.output||txt(CHALLENGE.empty))}</pre><div id="pythonInput" hidden><label id="pythonPrompt" for="pythonReply">${bi(CHALLENGE.inputs)}</label><input id="pythonReply"><button type="button" data-action="python-send">${optionLabel(CHALLENGE.send)}</button></div><div id="pythonRuns">${pythonRunsHTML()}</div>${question(FIELD[planField('pythonReflection')])}<p class="notice">${bi(CHALLENGE.pythonStretch)}</p>${question(FIELD[planField('pythonSupport')])}${optionalPaper('python')}</div>`;}
 const baseExtensionPage=extensionPage;extensionPage=function(){return current==='python'?pythonPage():baseExtensionPage();};
 let activeRun=null;
 function finishRun(message){if(!activeRun)return;if(message)pythonOutput+='\n'+message;activeRun.output=pythonOutput;activeRun.finished=now();(state.pythonRuns??=[]).push(activeRun);activeRun=null;save(true);if($('pythonConsole'))$('pythonConsole').textContent=pythonOutput;if($('pythonRuns'))$('pythonRuns').innerHTML=pythonRunsHTML();}
 function stopPython(show=true){if(worker){worker.terminate();worker=null;clearTimeout(workerTimer);finishRun(txt(show?B('Stopped.','Dihentikan.','已停止。'):B('Stopped when leaving this check.','Dihentikan apabila meninggalkan semakan ini.','离开本项检查时已停止。')));if($('pythonInput'))$('pythonInput').hidden=true;}}
 function runPython(){stopPython(false);const source=$('pythonCode').value;response(planField('pythonCode'),source);pythonOutput='';activeRun={checkId:planCheck(),pseudocode:ownCode(),code:source,at:now(),inputs:[]};try{worker=new Worker('python-worker.js?v=20260908-input-pause');}catch{finishRun(txt(B('The browser could not start Python here. Open the lesson through its GitHub Pages address, or download your .py file for a Python editor.','Pelayar tidak dapat memulakan Python. Buka melalui GitHub Pages atau muat turun fail .py untuk editor Python.','浏览器无法在这里启动 Python。请通过 GitHub Pages 打开，或下载 .py 文件到 Python 编辑器。')));return;}
  $('pythonConsole').textContent='';
  worker.onmessage=e=>{const m=e.data;if(m.type==='output'){pythonOutput+=m.text;if($('pythonConsole'))$('pythonConsole').textContent=pythonOutput;}if(m.type==='input'){clearTimeout(workerTimer);$('pythonInput').hidden=false;$('pythonPrompt').textContent=m.prompt||txt(CHALLENGE.inputs);$('pythonReply').value='';$('pythonReply').focus();}if(m.type==='done'||m.type==='error'){finishRun(m.type==='error'?m.error:'');worker?.terminate();worker=null;clearTimeout(workerTimer);if($('pythonInput'))$('pythonInput').hidden=true;}};
  worker.onerror=()=>{finishRun(txt(B('Python could not load. Use the hosted lesson or download your .py file.','Python tidak dapat dimuatkan. Gunakan pelajaran dihoskan atau muat turun fail .py.','Python 无法加载。请使用托管的课程网站，或下载 .py 文件。')));worker?.terminate();worker=null;clearTimeout(workerTimer);};worker.postMessage({type:'run',code:source});armPythonTimer();
 }
 function armPythonTimer(){clearTimeout(workerTimer);workerTimer=setTimeout(()=>{if(worker){finishRun(txt(B('Stopped: execution time limit reached.','Dihentikan: had masa pelaksanaan dicapai.','已停止：达到运行时间限制。')));worker.terminate();worker=null;if($('pythonInput'))$('pythonInput').hidden=true;toast(txt(B('Python stopped. Check for an endless loop and try again. Time spent answering input is not counted.','Python dihentikan. Semak gelung tanpa henti dan cuba lagi. Masa menjawab input tidak dikira.','Python 已停止。请检查无限循环后重试，等待你输入答案的时间不计入限制。')));}},60000);}
